import io.github.libtmux.control.ControlEvent
import io.github.libtmux.control.Delivery
import io.github.libtmux.control.PaneOutput
import kotlinx.coroutines.flow.Flow
import io.github.libtmux.control.ControlClient as JavaControlClient

/**
 * A tmux client that stays attached and answers one command at a time.
 *
 * Holds the Java handle privately, so a member here always wins over a same-named catalog-generated
 * extension in `ControlClientOperations.kt`.
 */
public class ControlClient internal constructor(
    internal val java: JavaControlClient,
    public val server: Server,
) : AutoCloseable {

    /** The Java control client this wraps: the same object, for a Java API that takes one. */
    public val asJava: JavaControlClient get() = java

    /** Whether the client is still running. */
    public val isAlive: Boolean get() = java.isAlive

    /** The error text captured from this control process, at most 4096 bytes. */
    public val standardError: String get() = java.standardError()

    /** Whether [standardError] stopped before the process finished writing it. */
    public val standardErrorTruncated: Boolean get() = java.standardErrorTruncated()

    /**
     * Terminal output tmux pushes, as a cold [Flow].
     *
     * A fresh Java subscription opens per [kotlinx.coroutines.flow.Flow.collect] and closes when
     * collection ends, cancels, or throws — fan-out means collecting twice, each with its own gap
     * accounting. Not `suspend`: opening the subscription is local and does no tmux round trip: only
     * collecting it reads.
     *
     * Output tmux sends before the subscription opens is not delivered, and a cold flow opens it
     * only when collection starts. So a command whose output is wanted belongs in [onSubscribed],
     * which runs once the subscription exists and before the first read, rather than before
     * `collect`: `control.output(32) { control.send("send-keys", ...) }`.
     */
    public fun output(capacity: Int, onSubscribed: suspend () -> Unit = {}): Flow<Delivery<PaneOutput>> =
        coldFlowFrom({ java.subscribeOutput(capacity) }, onSubscribed)

    /** State changes tmux volunteers, as a cold [Flow]. Reads, and takes [onSubscribed], as [output] does. */
    public fun events(capacity: Int, onSubscribed: suspend () -> Unit = {}): Flow<Delivery<ControlEvent>> =
        coldFlowFrom({ java.subscribeEvents(capacity) }, onSubscribed)

    /** Ends the client, rejecting queued requests and resolving picked requests as uncertain. */
    override fun close() {
        java.close()
    }
}

package io.github.libtmux.kotlin

import io.github.libtmux.SessionSpec
import io.github.libtmux.SplitSpec
import io.github.libtmux.WindowSpec
import java.nio.file.Path

/**
 * Marks every builder below so an inner block cannot reach an outer block's receiver by accident:
 * `split { directory = x }` inside `window { }` resolves to the innermost [SplitBuilder], never to
 * the [WindowBuilder] it is nested in. Reaching the outer receiver on purpose still works, spelled
 * explicitly (`this@window.directory = x`).
 */
@DslMarker
public annotation class LibTmuxDsl

/**
 * Declares a session's shape, then creates it: one session, its windows, and each window's splits,
 * as a single call lowering to the right sequence of suspend operations.
 *
 * tmux always gives a new session one window, and `new-session` itself names it, gives it its
 * directory and starts its command. So the first [window] block goes into that one command rather
 * than a rename afterwards, which could not move a shell already running; each later block is a
 * genuine [Session.newWindow], and `window { }` twice means exactly two windows, not three.
 *
 * @throws IllegalArgumentException if the session and its first window block both set a
 *     directory, or both set a command: tmux has one of each for that window
 */
public suspend fun Server.newSession(configure: SessionBuilder.() -> Unit): Session {
    val builder = SessionBuilder().apply(configure)
    val windowBlocks = builder.windows.iterator()
    val first = if (windowBlocks.hasNext()) WindowBuilder().apply(windowBlocks.next()) else null
    var session = newSession(builder.build(first))
    if (first != null) {
        val firstWindow = session.activeWindow ?: error("the session just created has no active window")
        applySplits(firstWindow, first)
    }
    for (windowBlock in windowBlocks) {
        val windowBuilder = WindowBuilder().apply(windowBlock)
        applySplits(session.newWindow(windowBuilder.build()), windowBuilder)
    }
    // The session handle returned by newSession(), and the one held since, are both the capture from
    // before any window/split was added — including the first window's own splits, which change its
    // pane count without changing the window count that would otherwise hint a refresh is needed — so
    // refresh whenever at least one window block ran, not only when a later block added a window.
    if (builder.windows.isNotEmpty()) {
        session = session.refresh()
    }
    return session
}

private suspend fun applySplits(window: Window, builder: WindowBuilder) {
    for (splitBlock in builder.splits) {
        val splitBuilder = SplitBuilder().apply(splitBlock)
        window.split(splitBuilder.build())
    }
}

/** Configure a new session, its initial command, and its windows with [Server.newSession]. */
@LibTmuxDsl
public class SessionBuilder internal constructor() {
    internal val windows: MutableList<WindowBuilder.() -> Unit> = mutableListOf()
    private var command: List<String>? = null
    private val environment: MutableMap<String, String> = mutableMapOf()

    public var name: String? = null

    /** The session's working directory, which its first window starts in too. */
    public var directory: Path? = null

    /** Runs [argv] in the first window instead of the default shell. */
    public fun running(vararg argv: String) {
        command = argv.toList()
    }

    /** Adds a variable to the new session's environment, keeping any already set. */
    public fun env(name: String, value: String) {
        environment[name] = value
    }

    public fun window(configure: WindowBuilder.() -> Unit) {
        windows += configure
    }

    internal fun build(first: WindowBuilder?): SessionSpec {
        val spec = SessionSpec.builder()
        name?.let { spec.named(it) }
        first?.name?.let { spec.firstWindowNamed(it) }
        require(directory == null || first?.directory == null || directory == first.directory) {
            "the session and its first window block both set a directory; tmux starts that window in one"
        }
        (first?.directory ?: directory)?.let { spec.`in`(it) }
        require(command == null || first?.command == null) {
            "the session and its first window block both set a command; that window runs one"
        }
        (first?.command ?: command)?.let { spec.running(*it.toTypedArray()) }
        environment.forEach { (envName, value) -> spec.env(envName, value) }
        return spec.build()
    }
}

/** Configure a window and its pane splits inside a [SessionBuilder] block. */
@LibTmuxDsl
public class WindowBuilder internal constructor() {
    internal val splits: MutableList<SplitBuilder.() -> Unit> = mutableListOf()
    internal var command: List<String>? = null
        private set
    private val environment: MutableMap<String, String> = mutableMapOf()

    public var name: String? = null

    public var directory: Path? = null

    /** Runs [argv] in this window instead of the default shell. */
    public fun running(vararg argv: String) {
        command = argv.toList()
    }

    /** Adds a variable to the new window's environment, keeping any already set. */
    public fun env(name: String, value: String) {
        environment[name] = value
    }

    public fun split(configure: SplitBuilder.() -> Unit = {}) {
        splits += configure
    }

    internal fun build(): WindowSpec {
        val spec = WindowSpec.builder()
        name?.let { spec.named(it) }
        directory?.let { spec.`in`(it) }
        command?.let { spec.running(*it.toTypedArray()) }
        environment.forEach { (envName, value) -> spec.env(envName, value) }
        return spec.build()
    }
}

/** Choose the position, size, and working directory of a new pane split. */
@LibTmuxDsl
public class SplitBuilder internal constructor() {
    private val java: SplitSpec.Builder = SplitSpec.builder()

    public var directory: Path? = null
        set(value) {
            field = value
            value?.let { java.`in`(it) }
        }

    /** Puts the new pane below this one. tmux's own default if no direction is chosen. */
    public fun below() {
        java.below()
    }

    /** Puts the new pane above this one. */
    public fun above() {
        java.above()
    }

    /** Puts the new pane to the right of this one. */
    public fun toRight() {
        java.toRight()
    }

    /** Puts the new pane to the left of this one. */
    public fun toLeft() {
        java.toLeft()
    }

    /** Sizes the new pane by an exact number of cells. */
    public fun cells(count: Int) {
        java.cells(count)
    }

    /** Sizes the new pane as a percentage of the space being split. */
    public fun percent(share: Int) {
        java.percent(share)
    }

    /** Adds a variable to the new pane's environment, keeping any already set. */
    public fun env(name: String, value: String) {
        java.env(name, value)
    }

    internal fun build(): SplitSpec = java.build()
}

package io.github.libtmux.kotlin

import io.github.libtmux.ServerConfig
import kotlin.time.Duration
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.Dispatchers

/**
 * Controls the dispatchers and concurrency limits for a [Server]'s suspending operations.
 *
 * Two independently sized pools, not one: [commands] backs every `suspend` operation this module
 * generates or hand-writes, sized from the transport's own admission bound rather than a guess.
 * [streamReads] backs only what still genuinely blocks a thread — [Server.liveState]'s background
 * pump. [ControlClient.output] and [ControlClient.events] hold no thread from either pool; they are
 * built on [io.github.libtmux.control.EventSubscription.poll] and `onReady`, not on a blocking read.
 */
public class ExecutionPolicy(
    public val commands: CoroutineDispatcher,
    public val streamReads: CoroutineDispatcher,
    public val defaultDeadline: Duration = Duration.INFINITE,
) {
    public companion object {
        private const val DEFAULT_STREAM_READ_CAPACITY = 16

        /**
         * Sizes [commands] from `config`'s own [ServerConfig.maxConcurrentCommands], and
         * [streamReads] independently: it bounds a structurally different resource, open
         * [Server.liveState] watches, not tmux process admission.
         */
        public fun default(
            config: ServerConfig,
            streamReadCapacity: Int = DEFAULT_STREAM_READ_CAPACITY,
        ): ExecutionPolicy = ExecutionPolicy(
            commands = Dispatchers.IO.limitedParallelism(config.maxConcurrentCommands()),
            streamReads = Dispatchers.IO.limitedParallelism(streamReadCapacity),
        )
    }
}

package io.github.libtmux.kotlin

import io.github.libtmux.query.FilterExpr
import io.github.libtmux.Client as JavaClient
import io.github.libtmux.Pane as JavaPane
import io.github.libtmux.Session as JavaSession
import io.github.libtmux.Window as JavaWindow

/**
 * Inverts an expression, so `!Pane_.active().isTrue()` says what it means.
 *
 * There is no matching `and` or `or` here, deliberately. Those are already methods on
 * [FilterExpr], and an extension of the same name would be shadowed by the member inside its own
 * body while winning at an infix call site — correct either way, but for a reason no reader should
 * have to work out. `a.and(b)` is one character longer than `a and b` and always means the thing it
 * appears to.
 *
 * `negate` rather than `not` on the Java side because [java.util.function.Predicate] already owns
 * `not`, and these expressions are predicates.
 *
 * The bound is `T : Any` rather than `T`, and that is not a style choice. The core is `@NullMarked`,
 * so Kotlin reads `FilterExpr` as `FilterExpr<T : Any>`; an unbounded `T` here would admit a
 * nullable entity the core says cannot exist. Compiled with `-Xjspecify-annotations=strict`, so it
 * is an error rather than a warning — this file did not compile until the bound was written.
 */
public operator fun <T : Any> FilterExpr<T>.not(): FilterExpr<T> = negate()

/**
 * Selects the elements an expression matches.
 *
 * Kotlin's own `filter` takes a function, not a [java.util.function.Predicate], so handing it a
 * [FilterExpr] does not compile — the one place where reading the Java documentation and writing
 * Kotlin part company. This is that overload, so `panes.filter(Pane_.active().isTrue())` means what
 * it appears to.
 *
 * The list is already in hand: this asks tmux nothing.
 */
public fun <T : Any> Iterable<T>.filter(expression: FilterExpr<T>): List<T> = filter(expression::test)

// Erasure collides these with the type-parameterized overload above (an Iterable<T>.filter(FilterExpr<T>)
// of any T is one JVM signature), so each needs its own @JvmName; the Kotlin-visible name stays `filter`.

/**
 * As the type-parameterized overload, for a list of wrapper [Session]s already in hand — filtering
 * against a query field expression such as `Session.name eq "build"` without a round trip to tmux.
 */
@JvmName("filterSessions")
public fun Iterable<Session>.filter(expression: FilterExpr<JavaSession>): List<Session> =
    filter { expression.test(it.java) }

/** As the [Session] overload, for wrapper [Window]s. */
@JvmName("filterWindows")
public fun Iterable<Window>.filter(expression: FilterExpr<JavaWindow>): List<Window> =
    filter { expression.test(it.java) }

/** As the [Session] overload, for wrapper [Pane]s. */
@JvmName("filterPanes")
public fun Iterable<Pane>.filter(expression: FilterExpr<JavaPane>): List<Pane> =
    filter { expression.test(it.java) }

/** As the [Session] overload, for wrapper [Client]s. */
@JvmName("filterClients")
public fun Iterable<Client>.filter(expression: FilterExpr<JavaClient>): List<Client> =
    filter { expression.test(it.java) }

