/**
 * A tmux pane, with operations for input, output, and layout.
 *
 * Holds the Java handle privately, so a member here always wins over a same-named catalog-generated
 * extension in `PaneOperations.kt`. [Companion] hosts the generated query field namespace
 * (`Pane.command`, `Pane.active`, ...).
 */
public class Pane internal constructor(internal val java: JavaPane, public val server: Server) {

    /** The Java pane this wraps: the same object, for a Java API that takes one. */
    public val asJava: JavaPane get() = java

    /** The pane's stable id. */
    public val id: PaneId get() = java.id()

    /** The pane's position, which shifts as neighbours come and go. */
    public val index: Int get() = java.index()

    /** Whether this was its window's active pane when captured. */
    public val active: Boolean get() = java.active()

    /** The command tmux reported running here. */
    public val currentCommand: String get() = java.currentCommand()

    /** Whether this pane floats, or null when the running tmux cannot say. */
    public val floating: Boolean? get() = java.floating().orElse(null)

    /** How large the pane was when captured, in terminal cells. */
    public val size: Dimensions get() = java.size()

    /** Where the pane's top-left corner sat in its window when captured, in terminal cells. */
    public val position: PanePosition get() = java.position()

    /** The pane title, which a program running inside it can change. */
    public val title: String get() = java.title()

    /** The working directory tmux reported for the pane. */
    public val currentPath: Path get() = java.currentPath()

    /** The process id of the program running in the pane, captured at the time of the read. */
    public val pid: Long? get() = java.pid().let { if (it.isPresent) it.asLong else null }

    /** Which sides of its window the pane touches. */
    public val edges: PaneEdges get() = java.edges()

    /** The window link this pane was reached through. A pure read of the capture. */
    public val window: Window get() = Window(java.window(), server)

    /** Collects commands fenced to the server incarnation that produced this pane. */
    public fun batch(): Batch = Batch(java.batch(), server)

    /** This pane's own hooks. */
    public fun hooks(): Hooks = Hooks(java.hooks(), server)

    /** This pane's own options. */
    public fun options(): Options = Options(java.options(), server)

    /**
     * Waits until [text] shows in this pane.
     *
     * Cancelling the coroutine interrupts the wait. That is not a timeout, and it does not stop a
     * program already running in the pane.
     *
     * @param timeout how long to keep looking, finite and not negative
     * @param every how long to leave between looks, at least 10 ms
     * @param dispatcher where the blocking wait runs
     * @return why the wait ended
     */
    public suspend fun awaitText(
        text: String,
        timeout: Duration,
        every: Duration = 50.milliseconds,
        dispatcher: CoroutineDispatcher = Dispatchers.IO,
    ): TextOutcome =
        runInterruptible(dispatcher) { java.awaitText(text, timeout.toJavaDuration(), every.toJavaDuration()) }

    /**
     * Waits until [settled] accepts this pane, read fresh from tmux before each test.
     *
     * Cancelling the coroutine interrupts the wait. That is not a timeout. A read already sent to
     * tmux is not taken back.
     *
     * @param timeout how long to keep looking, finite and not negative
     * @param every how long to leave between looks, at least 10 ms
     * @param dispatcher where the blocking wait runs
     * @return why the wait ended
     */
    public suspend fun await(
        timeout: Duration,
        every: Duration = 50.milliseconds,
        dispatcher: CoroutineDispatcher = Dispatchers.IO,
        settled: (Pane) -> Boolean,
    ): WakeReason =
        runInterruptible(dispatcher) {
            java.await({ fresh -> settled(Pane(fresh, server)) }, timeout.toJavaDuration(), every.toJavaDuration())
        }

    /**
     * Runs a shell command in this pane to its end, and answers with its exit status and output.
     *
     * Cancelling the coroutine interrupts the wait. The command keeps running in the pane; only the
     * wait for its end is what cancellation reaches.
     *
     * @param command a line of shell, run as `eval` would run it
     * @param timeout how long to wait for it to end
     * @param dispatcher where the blocking wait runs
     * @return the command's exit status and what it printed
     */
    public suspend fun run(
        command: String,
        timeout: Duration,
        dispatcher: CoroutineDispatcher = Dispatchers.IO,
    ): PaneRun = runInterruptible(dispatcher) { java.run(command, timeout.toJavaDuration()) }

    override fun equals(other: Any?): Boolean = other is Pane && java == other.java

    override fun hashCode(): Int = java.hashCode()

    override fun toString(): String = java.toString()

    public companion object
}

package io.github.libtmux.kotlin.query

import io.github.libtmux.query.FilterExpr
import io.github.libtmux.query.Fields
import java.util.regex.Pattern

/**
 * Kotlin-idiomatic wrappers over [Fields]' typed field handles, each holding the Java handle it
 * wraps. A value class, so this costs nothing beyond the Java object it already holds — the same
 * choice [io.github.libtmux.kotlin.Server]'s live handles reject, made here on purpose: a field
 * handle carries exactly one property, which is what makes the boxing tradeoff free.
 */
@JvmInline
public value class TextField<T : Any> internal constructor(private val java: Fields.TextField<T>) {
    public infix fun eq(value: String): FilterExpr<T> = java.`is`(value)
    public infix fun ne(value: String): FilterExpr<T> = java.isNot(value)
    public infix fun startsWith(value: String): FilterExpr<T> = java.startsWith(value)
    public infix fun endsWith(value: String): FilterExpr<T> = java.endsWith(value)
    public infix fun contains(value: String): FilterExpr<T> = java.contains(value)
    public infix fun matches(pattern: Pattern): FilterExpr<T> = java.matches(pattern)
    public infix fun oneOf(values: Collection<String>): FilterExpr<T> = java.`in`(values)
}

/** Build numeric comparisons for a captured tmux field. */
@JvmInline
public value class NumberField<T : Any> internal constructor(private val java: Fields.NumberField<T>) {
    public infix fun eq(value: Int): FilterExpr<T> = java.`is`(value)
    public infix fun ne(value: Int): FilterExpr<T> = java.isNot(value)
    public infix fun lessThan(value: Int): FilterExpr<T> = java.lessThan(value)
    public infix fun atMost(value: Int): FilterExpr<T> = java.atMost(value)
    public infix fun greaterThan(value: Int): FilterExpr<T> = java.greaterThan(value)
    public infix fun atLeast(value: Int): FilterExpr<T> = java.atLeast(value)
}

/** Match a captured boolean field against true or false. */
@JvmInline
public value class FlagField<T : Any> internal constructor(private val java: Fields.FlagField<T>) {
    public fun isTrue(): FilterExpr<T> = java.isTrue()
    public fun isFalse(): FilterExpr<T> = java.isFalse()
}

/** Match an object by the captured children related to it. */
@JvmInline
public value class ToManyField<T : Any, R : Any> internal constructor(private val java: Fields.ToManyRef<T, R>) {
    public infix fun any(predicate: FilterExpr<R>): FilterExpr<T> = java.any(predicate)
    public infix fun all(predicate: FilterExpr<R>): FilterExpr<T> = java.all(predicate)
    public infix fun none(predicate: FilterExpr<R>): FilterExpr<T> = java.none(predicate)
}

/** Match an object by one captured related object. */
@JvmInline
public value class ToOneField<T : Any, R : Any> internal constructor(private val java: Fields.ToOneRef<T, R>) {
    public infix fun matching(predicate: FilterExpr<R>): FilterExpr<T> = java.`is`(predicate)
}

package io.github.libtmux.kotlin

import io.github.libtmux.exception.DispatchException

/**
 * Retries [block] up to [times] more times after a [DispatchException] whose
 * [DispatchException.safeToRetry] says the exact same request can be sent again.
 *
 * No retry executor lives in this library: [DispatchException.safeToRetry] is computed by the
 * operation that threw it from its own catalogued idempotence, so this needs no per-call lookup and
 * composes with any retry library a caller already uses instead of replacing it.
 */
public suspend fun <T> retryIfSafe(times: Int = 1, block: suspend () -> T): T {
    repeat(times) {
        try {
            return block()
        } catch (failure: DispatchException) {
            if (!failure.safeToRetry()) throw failure
        }
    }
    return block()
}

package io.github.libtmux.kotlin

import io.github.libtmux.ServerConfig
import kotlin.time.Duration
import kotlin.time.toKotlinDuration
import kotlinx.coroutines.NonCancellable
import kotlinx.coroutines.withContext

/**
 * Opens a [Server], runs [block], and closes it — even if [block] throws or is cancelled.
 *
 * The rule this follows, stated once: the scope that acquired a Java `AutoCloseable` is the only
 * thing that closes it. [close][Server.close] runs with [NonCancellable] so a cancelled [block]
 * still releases the transport's threads.
 */
public suspend fun <R> withServer(
    config: ServerConfig,
    policy: ExecutionPolicy = ExecutionPolicy.default(config),
    block: suspend (Server) -> R,
): R {
    val server = Server.open(config, policy)
    try {
        return block(server)
    } finally {
        withContext(NonCancellable + policy.commands) { server.close() }
    }
}

/** As [withServer], for a [ControlClient] attached through [server]. */
public suspend fun <R> withControl(
    server: Server,
    session: Session,
    timeout: Duration = server.config.defaultTimeout().toKotlinDuration(),
    block: suspend (ControlClient) -> R,
): R {
    val control = server.control(session, timeout)
    try {
        return block(control)
    } finally {
        withContext(NonCancellable + server.policy.commands) { control.close() }
    }
}

package io.github.libtmux.kotlin

import io.github.libtmux.Channel
import io.github.libtmux.ServerConfig
import io.github.libtmux.ServerIdentity
import io.github.libtmux.exception.CardinalityException
import io.github.libtmux.exception.DispatchException
import io.github.libtmux.query.FilterExpr
import kotlin.time.Duration
import kotlin.time.toJavaDuration
import kotlin.time.toKotlinDuration
import kotlinx.coroutines.runInterruptible
import io.github.libtmux.Pane as JavaPane
import io.github.libtmux.Server as JavaServer
import io.github.libtmux.Session as JavaSession
import io.github.libtmux.Window as JavaWindow

/**
 * Manages sessions, windows, and panes on a tmux server.
 *
 * Use [open] with a [ServerConfig] to select a server by socket name or path. From this object,
 * create sessions or query the server's existing sessions, windows, and panes. Each [Session]
 * contains windows, and each [Window] contains panes.
 *
 * Operations that contact tmux are `suspend` functions dispatched through [policy]. Call [close]
 * after the last operation to release resources owned by this object. The tmux server and its
 * sessions keep running.
 *
 * [asJava] exposes the underlying [JavaServer] for interoperability. Both objects share the same
 * resources, so closing either closes both.
 */
public class Server private constructor(
    internal val java: JavaServer,
    public val policy: ExecutionPolicy,
) : AutoCloseable {

    /**
     * The Java server this wraps, for an operation this class does not mirror or a Java API that
     * takes one. The same object, not a copy: closing either closes both.
     */
    public val asJava: JavaServer get() = java

    /** How this server was configured. */
    public val config: ServerConfig get() = java.config()

    /** Which server this is. Every handle taken from it is scoped by this. */
    public val identity: ServerIdentity get() = java.identity()

    /** How many tmux commands this server's transport runs at once, from [ExecutionPolicy.default]. */
    public val admissionBound: Int get() = java.admissionBound()

    /** Collects several commands to run in one tmux invocation. */
    public fun batch(): Batch = Batch(java.batch(), this)

    /** Starts a chain of commands where each one acts on what the last one made. */
    public fun chain(): CommandChain = CommandChain(java.chain(), this)

    /** Shell commands run by tmux, and tmux commands chosen by a shell exit status. */
    public fun shell(): Shell = Shell(java.shell(), this)

    /** The commands this tmux knows. */
    public fun commands(): Commands = Commands(java.commands(), this)

    /** The server's message log. */
    public fun messageLog(): MessageLog = MessageLog(java.messageLog(), this)

    /** The command prompt's history. */
    public fun prompt(): Prompt = Prompt(java.prompt(), this)

    /** One of this server's wait-for channels, which is where a signal is sent and waited for. */
    public fun channel(name: String): Channel = java.channel(name)

    /** The server's key bindings: `prefix` when binding, every table when listing. */
    public fun keys(): Keys = Keys(java.keys(), this)

    /** The server's paste buffers, which every session shares. */
    public fun buffers(): Buffers = Buffers(java.buffers(), this)

    /** The server-wide options, the ones tmux keeps once per server. */
    public fun options(): Options = Options(java.options(), this)

    /** The global session options every session inherits unless it sets its own. */
    public fun globalOptions(): Options = Options(java.globalOptions(), this)

    /** The server's environment, which every session inherits and every new process is given. */
    public fun environment(): Environment = Environment(java.environment(), this)

    /** The global hooks every session inherits. */
    public fun hooks(): Hooks = Hooks(java.hooks(), this)

    /**
     * The one session this expression matches, captured now.
     *
     * @throws CardinalityException.NoMatch if nothing matched
     * @throws CardinalityException.MultipleMatches if more than one session matched
     */
    public suspend fun session(expression: FilterExpr<JavaSession>): Session =
        sessionOrNull(expression)
            ?: throw CardinalityException.NoMatch("expected exactly one session, found none")

    /** The one session this expression matches, or null when none does. */
    public suspend fun sessionOrNull(expression: FilterExpr<JavaSession>): Session? =
        runInterruptible(policy.commands) {
            java.session(expression).map { Session(it, this) }.orElse(null)
        }

    /**
     * The one window link this expression matches, captured now.
     *
     * @throws CardinalityException.NoMatch if nothing matched
     * @throws CardinalityException.MultipleMatches if more than one link matched
     */
    public suspend fun window(expression: FilterExpr<JavaWindow>): Window =
        windowOrNull(expression)
            ?: throw CardinalityException.NoMatch("expected exactly one window, found none")

    /** The one window link this expression matches, or null when none does. */
    public suspend fun windowOrNull(expression: FilterExpr<JavaWindow>): Window? =
        runInterruptible(policy.commands) {
            java.window(expression).map { Window(it, this) }.orElse(null)
        }

    /**
     * The one pane this expression matches, captured now.
     *
     * @throws CardinalityException.NoMatch if nothing matched
     * @throws CardinalityException.MultipleMatches if more than one pane matched
     */
    public suspend fun pane(expression: FilterExpr<JavaPane>): Pane =
        paneOrNull(expression) ?: throw CardinalityException.NoMatch("expected exactly one pane, found none")

    /** The one pane this expression matches, or null when none does. */
    public suspend fun paneOrNull(expression: FilterExpr<JavaPane>): Pane? =
        runInterruptible(policy.commands) {
            java.pane(expression).map { Pane(it, this) }.orElse(null)
        }

    /**
     * Attaches a control client to this session's server, and only to the process this capture
     * named.
     *
     * @param timeout how long to wait for the client to become ready
     */
    public suspend fun control(
        session: Session,
        timeout: Duration = config.defaultTimeout().toKotlinDuration(),
    ): ControlClient =
        runInterruptible(policy.commands) {
            try {
                ControlClient(java.control(session.java, timeout.toJavaDuration()), this)
            } catch (failed: DispatchException.Failed) {
                // ControlWriter.await catches its own InterruptedException and reports it as a
                // checked DispatchException.Failed — the right call for a caller with no coroutine
                // concept, but it swallows the raw InterruptedException runInterruptible (above)
                // needs to translate a cancelling interrupt into a CancellationException. Nothing
                // else interrupts this thread, so an interrupted cause here always means this call
                // was cancelled, never a genuine dispatch failure; reinstate it.
                throw failed.cause as? InterruptedException ?: failed
            }
        }

    /** Releases an owned transport. Idempotent, and never kills tmux. */
    override fun close() {
        java.close()
    }

    public companion object {

        /** A server over a transport it owns and closes. */
        public suspend fun open(
            config: ServerConfig,
            policy: ExecutionPolicy = ExecutionPolicy.default(config),
        ): Server = runInterruptible(policy.commands) { Server(JavaServer.open(config), policy) }

        /**
         * A wrapper over a server opened in Java, such as a test fixture's. It takes the server as
         * it is: closing the wrapper closes it.
         */
        public fun fromJava(
            server: JavaServer,
            policy: ExecutionPolicy = ExecutionPolicy.default(server.config()),
        ): Server = Server(server, policy)
    }
}

